def chk(tag: str, m, cc: List[float], clp: List[float], pred: List[float], proba: List[float], jll: List[float]):
    check(close(m.class_count_, cc), tag + " cc")
    check(close(m.class_log_prior_, clp), tag + " clp")
    check(close(m.predict(Q), pred), tag + " pred")
    check(close(m.predict_proba(Q), proba), tag + " proba")
    check(close(m.predict_joint_log_proba(Q), jll), tag + " jll")

